4	
5	/**
6	 * Animated count-up stat. Starts at 0 and eases up to `value` the first time it
7	 * scrolls into view (IntersectionObserver). Respects prefers-reduced-motion.
8	 */
9	export function StatCounter({
10	  value,
11	  prefix = "",
12	  suffix = "",
13	  decimals = 0,
14	  duration = 1400,
15	  label,
16	}: {
17	  value: number;
18	  prefix?: string;
19	  suffix?: string;
20	  decimals?: number;
21	  duration?: number;
22	  label: string;
23	}) {
24	  const ref = useRef<HTMLDivElement | null>(null);
25	  const [display, setDisplay] = useState(0);
26	  const started = useRef(false);
27	
28	  useEffect(() => {
29	    const el = ref.current;
30	    if (!el) return;
31	
32	    const reduce =
33	      typeof window !== "undefined" &&
34	      window.matchMedia?.("(prefers-reduced-motion: reduce)").matches;
35	
36	    const run = () => {
37	      if (started.current) return;
38	      started.current = true;
39	      if (reduce) {
40	        setDisplay(value);
41	        return;
42	      }
43	      const start = performance.now();
44	      const tick = (now: number) => {
45	        const t = Math.min(1, (now - start) / duration);
46	        // easeOutCubic
47	        const eased = 1 - Math.pow(1 - t, 3);
48	        setDisplay(value * eased);
49	        if (t < 1) requestAnimationFrame(tick);
50	        else setDisplay(value);
51	      };
52	      requestAnimationFrame(tick);
53	    };
54	
55	    if (typeof IntersectionObserver === "undefined") {
56	      run();
57	      return;
58	    }
59	    const io = new IntersectionObserver(
60	      (entries) => {
61	        for (const e of entries) {
62	          if (e.isIntersecting) {
63	            run();
64	            io.disconnect();
65	          }
66	        }
67	      },
68	      { threshold: 0.4 },
69	    );
70	    io.observe(el);
71	    return () => io.disconnect();
72	  }, [value, duration]);
73	
74	  return (
75	    <div ref={ref} className="text-center">
76	      <p className="text-4xl font-bold tracking-tight grad-text sm:text-5xl tabular-nums">
77	        {prefix}
78	        {display.toLocaleString(undefined, {
79	          minimumFractionDigits: decimals,
80	          maximumFractionDigits: decimals,
81	        })}
82	        {suffix}
83	      </p>
84	      <p className="mt-2 text-sm text-slate-400">{label}</p>
85	    </div>
86	  );
87	}
