  title: "Web Hosting",
  description:
    "Fast, simple shared web hosting — host your website with PHP, MySQL databases, email and free SSL, without managing a server. Point your domain and you're live. Free migration from your current host.",
};

const money = (c: number) => `$${(c / 100).toFixed(2)}`;

const STEPS = [
  { n: "1", title: "Pick a plan", body: "Choose the storage and site count you need. No setup fee, and you can upgrade or move to a VPS later on the same account." },
  { n: "2", title: "Point your domain", body: "Add one DNS record — an A record to our shared IP. Free SSL is issued automatically the moment it resolves." },
  { n: "3", title: "Install & go live", body: "One-click WordPress (or Joomla, Drupal, Matomo and more), upload over SFTP, and manage databases and email from your dashboard." },
];

const FEATURES = [
  { icon: <IconBolt />, title: "PHP + MySQL, ready to go", body: "Modern PHP with per-account isolation and MySQL/MariaDB databases. WordPress, Laravel, or plain HTML — it just runs." },
  { icon: <IconShield />, title: "Free SSL, automatic", body: "HTTPS is issued and renewed for every domain automatically the moment it points at us. Nothing to configure." },
  { icon: <IconGlobe />, title: "Point your domain, done", body: "One DNS record and your site is live on a fast, hardened server — a WAF and malware scanning included." },
  { icon: <IconDisk />, title: "SSD storage + quotas", body: "Fast NVMe-backed storage with a clear per-plan quota. Upload over SFTP; manage databases from your dashboard." },
  { icon: <IconMail />, title: "Email on your domain", body: "Professional mailboxes on your own domain, alongside your site — one bill, one login." },
  { icon: <IconGauge />, title: "Grow into a VPS anytime", body: "Outgrow shared hosting? Move up to a full Nxeon VPS with root access whenever you're ready — same account." },
];

const HOSTING_FAQ = [
  { q: "What can I host?", a: "Any PHP or static site — WordPress, Laravel, Joomla, Drupal, phpBB, plain HTML and more. Each account gets modern PHP with a version switcher, MySQL/MariaDB databases, and per-account isolation." },
  { q: "How do I point my domain to my hosting?", a: "Every account is served from a shared IP address shown in your dashboard. Add a single A record at your domain's DNS pointing to that IP, and your site goes live. Free SSL (HTTPS) is issued and renewed automatically once the record resolves — nothing to configure." },
  { q: "Is my site isolated from other customers?", a: "Yes. Each account runs under its own locked-down system user with its own PHP pool, a disk quota, chrooted SFTP, and a database user scoped to only its own databases. A web application firewall and nightly malware scanning run on every box." },
  { q: "Can I move my existing website over?", a: "Yes — migration from your current host is free. Start it from the Migrate page and we'll bring your files, databases and configuration across, then help you cut the domain over with no downtime." },
  { q: "Do I get email with my hosting?", a: "You can add professional mailboxes on your own domain alongside your site, managed from the same dashboard and one bill." },
  { q: "What if I outgrow shared hosting?", a: "Move up to a full Nxeon VPS with root access whenever you're ready, on the same account — you're never boxed in by the entry tier." },
];

export default async function WebHostingPage() {
  const plans = await db.hostingPlan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } });

  // The single sitewide promo: first month free, then renews at the regular
  // price shown — same offer surfaced on the VPS and Business Email pages.
  const promo = currentPromo(new Date());

  // "From" price anchor — cheapest active hosting plan, read live from the DB
