      </div>

      <div className="relative z-10">
        <PageHero
          eyebrow="Web Hosting"
          title="Get your website online"
          highlight="without managing a server"
          sub="We run PHP, databases, email and SSL for you. Point your domain at us and you're live — with free migration from your current host."
          primary={{ label: "Get started", href: "/dashboard/hosting" }}
          secondary={{ label: "See plans", href: "#plans" }}
        >
          <div className="mt-8 flex flex-col items-center gap-5">
            {fromCents != null && (
              <div className="flex flex-wrap items-center justify-center gap-3">
                <span className="inline-flex items-center gap-2 rounded-full border border-brand-500/30 bg-brand-500/[0.08] px-4 py-1.5 text-sm">
