                const popular = i === popularIdx;
                return (
                  <Reveal
                    key={p.id}
                    delay={i * 60}
                    className={`card lift relative flex h-full flex-col ${popular ? "border-brand-500/40 glow-brand" : ""}`}
                  >
                    {popular && (
                      <span className="absolute -top-3 left-1/2 -translate-x-1/2 rounded-full border border-brand-500/30 bg-brand-500/15 px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.12em] text-brand-200">
                        Most popular
                      </span>
