                    <h3 className="text-lg font-semibold text-white">{p.name}</h3>
                    <span className="mt-2 inline-block w-fit rounded-md bg-emerald-500/15 px-1.5 py-0.5 text-[10px] font-bold uppercase tracking-wide text-emerald-300">
                      First month free
                    </span>
                    <p className="mt-1 text-3xl font-bold text-white">
                      {money(p.priceCents)}<span className="text-sm font-normal text-slate-400">/mo</span>
                    </p>
                    <p className="mt-1 text-[11px] leading-snug text-slate-500">
                      $0 today, then {money(p.priceCents)}/mo. Cancel anytime.
                    </p>
                    <ul className="mt-4 flex-1 space-y-2 text-sm text-slate-300">
                      {[
                        `${p.diskGB} GB SSD storage`,
                        `${p.maxSites} website${p.maxSites === 1 ? "" : "s"}`,
                        `${p.maxDatabases} MySQL database${p.maxDatabases === 1 ? "" : "s"}`,
                        `${p.bandwidthTB} TB bandwidth`,
                        "Free SSL + email + SFTP",
                      ].map((f) => (
                        <li key={f} className="flex items-start gap-2.5">
                          <span className="mt-0.5 flex h-[18px] w-[18px] shrink-0 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400">
                            <IconCheck size={12} />
                          </span>
                          {f}
                        </li>
                      ))}
                    </ul>
                    <Link
                      href="/dashboard/hosting"
                      className={`mt-6 w-full ${popular ? "btn-primary" : "btn-secondary"} px-5 py-3 text-center text-base`}
                    >
                      Get started
                      {popular && <IconArrow size={16} />}
                    </Link>
                  </Reveal>
                );
              })}
            </div>
          )}
        </Section>

        <Section size="lg">
          <SectionTitle
            eyebrow="Everything included"
            title="Everything a website needs, handled"
            sub="No server to patch, no stack to configure — just your site."
          />
          <div className="mt-12 grid gap-5 sm:grid-cols-2 lg:grid-cols-3">
            {FEATURES.map((f, i) => (
              <FeatureCard key={f.title} icon={f.icon} title={f.title} delay={(i % 3) * 60}>
                {f.body}
              </FeatureCard>
            ))}
          </div>
        </Section>

        <Section tone="panel" size="lg">
          <SectionTitle
            eyebrow="How it works"
            title="Live in three steps"
            sub="No server admin, no command line — the platform does the heavy lifting."
          />
          <div className="mt-12 grid gap-5 lg:grid-cols-3">
            {STEPS.map((s, i) => (
              <Reveal key={s.n} delay={i * 60} className="card relative">
                <span className="flex h-9 w-9 items-center justify-center rounded-full border border-brand-500/30 bg-brand-500/10 text-sm font-bold text-brand-200">{s.n}</span>
                <h3 className="mt-4 text-lg font-semibold text-white">{s.title}</h3>
                <p className="mt-1.5 text-sm leading-relaxed text-slate-400">{s.body}</p>
              </Reveal>
            ))}
          </div>
          <Reveal delay={200} className="mt-6 flex items-center justify-center gap-2 text-sm text-slate-400">
            <IconApps size={16} />
            One-click installs for WordPress, Joomla, Drupal, phpBB, Matomo &amp; Grav.
          </Reveal>
        </Section>

        <Section size="lg">
          <SectionTitle eyebrow="FAQ" title="Web hosting questions, answered" />
          <div className="mx-auto mt-10 max-w-3xl space-y-4">
            {HOSTING_FAQ.map((f, i) => (
              <Reveal key={f.q} delay={i * 60}>
                <div className="card">
                  <h3 className="flex items-start gap-2 text-base font-semibold text-white">
                    <span className="mt-0.5 text-brand-300"><IconCheck size={16} /></span>
                    {f.q}
                  </h3>
                  <p className="mt-2 pl-6 text-sm leading-relaxed text-slate-400">{f.a}</p>
                </div>
              </Reveal>
            ))}
          </div>
        </Section>

        <Section tone="deep" size="lg">
          <CtaBand />
        </Section>
      </div>
    </div>
  );
}

